inputs = ['yzbbij', 'bxhja', 'bfij', 'zxvk', 'bw']
outputs = ['yzbbij', 'bxywxja', 'bfij', 'zxgyy', 'bw']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

# Let me analyze character by character differences
print("\nDetailed analysis:")
for i in range(len(inputs)):
    print(f"Input: '{inputs[i]}', Output: '{outputs[i]}'")
    if inputs[i] != outputs[i]:
        print("  Differences:")
        # Find where they differ
        for j in range(max(len(inputs[i]), len(outputs[i]))):
            in_char = inputs[i][j] if j < len(inputs[i]) else None
            out_char = outputs[i][j] if j < len(outputs[i]) else None
            if in_char != out_char:
                print(f"    Position {j}: '{in_char}' -> '{out_char}'")
    else:
        print("  No changes")

